SELECT CASE WHEN to_regprocedure('public.refresh_dashboard_views()') IS NULL THEN 'ok' WHEN has_function_privilege('anon', 'public.refresh_dashboard_views()', 'EXECUTE') THEN 'FALHOU: anon ainda executa refresh_dashboard_views()' WHEN has_function_privilege('authenticated', 'public.refresh_dashboard_views()', 'EXECUTE') THEN 'FALHOU: authenticated ainda executa refresh_dashboard_views()' ELSE 'ok' END;
